Subroutine Suspendable Productor(canal As Channel<Integer>)
  For i <- 1 To 3 Do
    If Not Await canal.send(i * 10) Then
      Break;
    EndIf
  EndFor
  canal.close();
EndSubroutine

Algorithm Tuberia
  Define canal As Channel<Integer> <- channel(2);
  Tasks
    Spawn Productor(canal);
    Define seguir As Boolean <- True;
    While seguir Do
      Switch Await canal.receive() Do
        Some(valor):
          Write "recibido ", valor;
        None:
          seguir <- False;
      EndSwitch
    EndWhile
  EndTasks
EndAlgorithm

Subroutine Suspendable Avisar(canal As Channel<String>)
  If Await canal.send("aviso urgente") Then
    canal.close();
  EndIf
EndSubroutine

Subroutine Anunciar(origen As String, mensaje As Optional<String>)
  Switch mensaje Do
    Some(texto): Write origen, ": ", texto;
    None: Write origen, ": cerrado";
  EndSwitch
EndSubroutine

Algorithm Elige
  Define noticias As Channel<String> <- channel(1);
  Define avisos As Channel<String> <- channel(1);
  Tasks
    Spawn Avisar(avisos);
    Select
      Receive n From noticias:
        Anunciar("noticias", n);
      Receive a From avisos:
        Anunciar("avisos", a);
    EndSelect
  EndTasks
EndAlgorithm
